// 한자 4글자와 한글 4글자를 결합하여 글자별 [한자, 음, 훈(뜻)] 배열 반환
function getCharBreakdown(idiom) {
  const chars = [];
  const hLen = idiom.hanja.length;
  const wLen = idiom.word.length;
  for (let i = 0; i < hLen; i++) {
    const hChar = idiom.hanja[i];
    const sound = i < wLen ? idiom.word[i] : "";
    const hun = HANJA_HUN_MAP[hChar] || "뜻";
    chars.push({
      hanja: hChar,
      sound: sound,
      hun: hun,
      fullLabel: `${hun} ${sound}`
    });
  }
  return chars;
}

// 사자성어의 중학생 맞춤형 학습 카드 데이터(쉬운 설명, 예문, 유래, 상황 문제) 생성
function getEnrichedIdiom(idiom) {
  const breakdown = getCharBreakdown(idiom);
  const literalMeaning = breakdown.map(c => `'${c.hun}(${c.hanja})'`).join(" + ");
  const special = SPECIAL_IDIOM_CONTEXT[idiom.word];

  if (special) {
    return {
      ...idiom,
      breakdown,
      easyExplanation: special.easy,
      exampleSentence: special.example,
      originStory: special.story,
      situationPrompt: special.situation
    };
  }

  // 카테고리별 자연스러운 중학생 맞춤 예문 및 유래 생성
  let example = "";
  let situation = "";
  const cat = idiom.category || "";

  if (cat.includes("학문") || cat.includes("노력") || cat.includes("성장") || cat.includes("희망")) {
    example = `기말고사 목표를 세우고 '${idiom.word}(${idiom.hanja})'의 자세로 꾸준히 실천한 끝에 성적이 크게 올랐다.`;
    situation = `학교생활에서 '${idiom.meaning}'의 자세로 포기하지 않고 목표를 향해 정진하는 상황.`;
  } else if (cat.includes("우정") || cat.includes("관계") || cat.includes("협력") || cat.includes("공감")) {
    example = `모둠 프로젝트를 함께 해결하면서 친구들과 '${idiom.word}(${idiom.hanja})'의 소중한 의미를 깊이 깨달았다.`;
    situation = `친구들과의 관계에서 '${idiom.meaning}'에 어울리는 모습을 보여 준 상황.`;
  } else if (cat.includes("언행") || cat.includes("대화") || cat.includes("태도") || cat.includes("반성")) {
    example = `국어 시간 토론 수업에서 '${idiom.word}(${idiom.hanja})'이라는 성어를 인용해 내 주장을 설득력 있게 발표했다.`;
    situation = `일상 대화나 행동 중에 '${idiom.meaning}'의 모습이 나타난 상황.`;
  } else if (cat.includes("위기") || cat.includes("곤경") || cat.includes("상황")) {
    example = `동아리 대회 준비 중 예상치 못한 문제가 생겨 '${idiom.word}(${idiom.hanja})'의 상황에 놓였지만 침착하게 해결했다.`;
    situation = `예상치 못한 일이 벌어져 '${idiom.meaning}'에 처하게 된 상황.`;
  } else if (cat.includes("가족") || cat.includes("효도") || cat.includes("사랑")) {
    example = `가족들과 주말 저녁을 함께하며 '${idiom.word}(${idiom.hanja})'의 따뜻한 가르침을 다시금 되새겼다.`;
    situation = `가정이나 가족 사이에서 '${idiom.meaning}'의 마음이 잘 드러난 상황.`;
  } else {
    example = `오늘 역사 책에서 배운 '${idiom.word}(${idiom.hanja})'의 뜻을 떠올리며 일기장에 내 생각을 정리해 보았다.`;
    situation = `일상생활이나 학교에서 '${idiom.meaning}'이라고 표현하기에 가장 알맞은 상황.`;
  }

  const easyExp = `한자 글자 그대로 풀면 ${literalMeaning}의 결합으로, 쉽게 말해 "${idiom.meaning}"라는 뜻이에요.`;
  const storyExp = `${breakdown.map(c => `${c.hanja}(${c.hun} ${c.sound})`).join("·")} 네 글자가 합쳐진 성어로, 옛 선현들의 지혜와 역사 이야기 속에서 유래하여 오늘날 [${idiom.category}] 분야의 핵심 표현으로 널리 쓰여요.`;

  return {
    ...idiom,
    breakdown,
    easyExplanation: easyExp,
    exampleSentence: example,
    originStory: storyExp,
    situationPrompt: situation
  };
}
